import {getAction} from '@madou/catalog';
import {createGame,gameStats} from '@madou/engine';
import {assignCharacter,entropy,takeCard,trimHand} from './scenario-tools.js';
export const castleImpPhysicalScenarios=['castle-setup','castle-turn','imp-setup','imp-turn','imp-magic4','imp-magic5','imp-magic6','imp-mixed','imp-army','imp-army-reflect'] as const;
export type CastleImpPhysicalScenario=typeof castleImpPhysicalScenarios[number];
export function isCastleImpPhysicalScenario(name:string):name is CastleImpPhysicalScenario{return (castleImpPhysicalScenarios as readonly string[]).includes(name);}
export function castleImpPhysicalMode(name:CastleImpPhysicalScenario){const castle=name.startsWith('castle');return{card:castle?'a2-p19-r3c1':'a2-p19-r3c2',name:castle?'城':'小悪魔',level:4,hp:castle?5:0,attributes:castle?['建']:['黒','飛'],army:name.includes('-army'),reflect:name.endsWith('-reflect'),magic:name.includes('-magic'),magicLevel:name.endsWith('4')?4:name.endsWith('5')?5:6,mixed:name.endsWith('-mixed'),initial:name.endsWith('-setup')||name.includes('-magic')||name.endsWith('-mixed')};}
/** Every scenario starts in real initial placement; tests issue all placement and turn commands. */
export function makeCastleImpPhysicalScenario(name:CastleImpPhysicalScenario,players:{id:string;name:string}[],options:{dwarf?:boolean;level?:number;owner?:string;magic?:number;armyCard?:boolean}={}){
 const m=castleImpPhysicalMode(name),s=createGame(players,entropy(),{startingSeat:0}),[a,b,c,d]=players.map(p=>p.id) as [string,string,string,string];for(const [i,p] of players.entries())assignCharacter(s,p.id,[options.dwarf||m.mixed?'魔導王ガイナス':options.owner??'魔聖母ディア',options.dwarf||m.mixed?'魔聖母ディア':'白魔術師シェリム','凍気のアイエル','侍大将のシン'][i]!);for(const p of Object.values(s.players)){p.permanent={endurance:100,warrior_level:20,magic_level:20,spirit:20};p.permanent.spirit=20+14-gameStats(s,p.id).spirit;}if(options.level!==undefined||m.mixed)s.players[b]!.permanent!.warrior_level=20+(options.level??5)-gameStats(s,b).warrior_level;
 if(options.magic!==undefined)s.players[a]!.permanent!.magic_level=20+options.magic-gameStats(s,a).magic_level;
 const keep=[takeCard(s,a,m.card),takeCard(s,a,'a2-p24-r1c3'),takeCard(s,a,'a2-p22-r1c1'),takeCard(s,a,m.army||options.armyCard?'a2-p05-r2c2':'a2-p23-r1c1'),takeCard(s,a,'a2-p07-r1c1'),takeCard(s,b,'a2-p24-r1c2'),takeCard(s,b,'a2-p24-r2c1'),takeCard(s,b,'a2-p21-r2c3'),...(m.magic?[takeCard(s,b,m.magicLevel===4?'a2-p17-r2c1':m.magicLevel===5?'a2-p17-r2c2':'a2-p18-r1c3')]:m.mixed?[takeCard(s,b,'a2-p21-r2c1')]:m.army?[takeCard(s,b,'a2-p11-r1c3')]:[]),takeCard(s,d,'a2-p02-r2c3')];for(const p of players)trimHand(s,p.id,...keep);s.deck=[...s.deck.filter(id=>getAction(id)!.category!=='open'),...s.deck.filter(id=>getAction(id)!.category==='open')];// The scripted deal replaces createGame's random initial deal before any commands.
 // Keep the initial private log consistent with those preconditions.
 const cursors:Record<string,number>={};s.events=s.events.flatMap(event=>{if(event.type==='CHARACTER_ASSIGNED'&&event.actorId)return[{...event,characterId:s.players[event.actorId]!.characterId}];if(event.type!=='CARD_DRAWN'||!event.actorId)return[event];const index=cursors[event.actorId]??0;cursors[event.actorId]=index+1;const cardInstanceId=s.players[event.actorId]!.hand[index];return cardInstanceId?[{...event,cardInstanceId}]:[];});return s;
}
